import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Nushell.html","title":"Nushell","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":2.17,"words":651},"filePathRelative":"Nushell.md"}`),a={name:`Nushell.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="nushell" tabindex="-1"><a class="header-anchor" href="#nushell"><span>Nushell</span></a></h1><p>SelectとかWhereとか使える感じの<a href="./Shell.html">Shell</a>。<a href="./GoFO.html">GoFO</a>と似ている気がするな。</p><ul><li>公式: <a href="https://www.nushell.sh/" target="_blank" rel="noopener noreferrer">Nushell</a></li></ul><h2 id="getにanyを渡すと何が起こるか" tabindex="-1"><a class="header-anchor" href="#getにanyを渡すと何が起こるか"><span>getにAnyを渡すと何が起こるか</span></a></h2><p>例えば以下のようなスクリプトがある。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&gt; ls | first | get name</span>
<span class="line">README.md</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>getのinputは以下になっている。</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line">            <span class="token punctuation">.</span><span class="token function">input_output_types</span><span class="token punctuation">(</span><span class="token macro property">vec!</span><span class="token punctuation">[</span></span>
<span class="line">                <span class="token punctuation">(</span></span>
<span class="line">                    <span class="token comment">// TODO: This is too permissive; if we could express this</span></span>
<span class="line">                    <span class="token comment">// using a type parameter it would be List&lt;T&gt; -&gt; T.</span></span>
<span class="line">                    <span class="token class-name">Type</span><span class="token punctuation">::</span><span class="token class-name">List</span><span class="token punctuation">(</span><span class="token class-name">Box</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span><span class="token class-name">Type</span><span class="token punctuation">::</span><span class="token class-name">Any</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">                    <span class="token class-name">Type</span><span class="token punctuation">::</span><span class="token class-name">Any</span><span class="token punctuation">,</span></span>
<span class="line">                <span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">                <span class="token punctuation">(</span><span class="token class-name">Type</span><span class="token punctuation">::</span><span class="token function">table</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">Type</span><span class="token punctuation">::</span><span class="token class-name">Any</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">                <span class="token punctuation">(</span><span class="token class-name">Type</span><span class="token punctuation">::</span><span class="token function">record</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token class-name">Type</span><span class="token punctuation">::</span><span class="token class-name">Any</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">                <span class="token punctuation">(</span><span class="token class-name">Type</span><span class="token punctuation">::</span><span class="token class-name">Nothing</span><span class="token punctuation">,</span> <span class="token class-name">Type</span><span class="token punctuation">::</span><span class="token class-name">Nothing</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">            <span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Anyがこれらの型のどれとして処理されるのかを追ってみる。</p><p>parse_pipelineの段階ではexprの型を次のparse_pipeline_elementのinputに渡しているように見える。だからこの時点ではAnyが渡されているはず。 parse_pipeline_elementは最終的にはparse_callのinputに渡されて、これはparse_internal_callに渡される。</p><p>ここでは、signature.get_output_typeに渡していて、これはinput_typeがassignableなものを集めてUnionにしている。</p><p>なお、実行はget.rsのactionが呼ばれて、これはValueにしてValueのfollow_cell_pathを呼んでいる。 これはget_value_memberが呼ばれて、memberがStringの時はRecordだったらうんたら、みたいな処理がある。</p><h2 id="tableとlistの型" tabindex="-1"><a class="header-anchor" href="#tableとlistの型"><span>TableとListの型</span></a></h2><p>lsの結果はTableだが、<code>ls | first</code>の結果はRecordになる。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&gt; ls | first | describe</span>
<span class="line">record&lt;name: string, type: string, size: filesize, modified: datetime&gt;</span>
<span class="line">&gt; ls | describe</span>
<span class="line">table&lt;name: string, type: string, size: filesize, modified: datetime&gt; (stream)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>firstは<code>List&lt;Any&gt;</code>から<code>Any</code>となっている。</p><p>TableをListとして扱うのはどこで処理しているのかを見ると、どうもty.rsのcompare_typesっぽい。</p><p>確かにここで<code>List&lt;Any&gt;</code>はTableのサブタイプ、としている。</p><p>ではfirstの実行時にはTableの時にどう処理するのか？というと、実行時はPipelineDataというものになり、 これはValueとかListStreamとかの種類がある。</p><p>とりあえずストリーミングを無視してValueを見ると、ListだとかRangeだとかの処理があり、Tableの処理は無さそう。</p><p>Tableの時にValueが何になるかを追いたいが、ls.rsは結構複雑で追うのにいまいち。 Tableリテラルを追ってみようか。</p><p><a href="https://www.nushell.sh/lang-guide/chapters/types/basic_types/table.html#table-literal-syntax" target="_blank" rel="noopener noreferrer">Table#table literal syntax</a></p><p>parse_exrepssions.rsにparse_table_expressionというのがあり、Expr::Tableとして中にTable構造体を入れて返している。 これを実行時にどうしているかを見ればいいが、 どこを見るのかな。検索した範囲ではそれっぽいのはcompile/expression.rsとeval_base.rsか。</p><p>eval_base.rsではValue::listにレコードを入れている。</p><p>compile/expression.rsではバイトコードでListPushを最後にpushしているので、やはりListを作っていそうだな。 つまりTableの実行時の値はValue::listとなる。なるほど。</p><h3 id="valueの型" tabindex="-1"><a class="header-anchor" href="#valueの型"><span>Valueの型</span></a></h3><p>src/value/mod.rsにValueの定義があって、Int, String, Float, Date, List, Record等となっている。 これらはenumで、だいたい同じ名前の構造体が定義されててそれを保持するようになっている。 ふむふむ。</p><h2 id="restパラメータ" tabindex="-1"><a class="header-anchor" href="#restパラメータ"><span>restパラメータ</span></a></h2><p>ls.rsを読んでいて、restパラメータについてどうしてこの記述で複数パラメータとなるのかが疑問に思ったので少し調べる。 以下を見ると、restは最後の...の要素となる。</p><p><a href="https://www.nushell.sh/book/custom_commands.html#rest-parameters" target="_blank" rel="noopener noreferrer">Custom Commands - Nushell</a></p><p>だからいつも0個以上の繰り返しで同じ型となる（ただしその型がOneOfだったりするのはOKだしLsは実際にGlobとStringのOneOf）。</p><h2 id="full-parseの型の解決" tabindex="-1"><a class="header-anchor" href="#full-parseの型の解決"><span>Full Parseの型の解決</span></a></h2><p>lsなどの引数がどう解決されているかを理解したい。</p><p>parse_blockやparse_pipelineなどでFull Parseしている雰囲気で、最終的にparse_callになっているように見える。</p><p>LsとかはCommandをimplしてstate_working_setのadd_declに渡している感じに見える。</p><p>parse_callを見ていくとLsとかはparse_internal_callに行くのか？</p><p>parse_internal_callはめちゃくちゃ複雑だな。</p><p>Lsはrestに以下が指定されている。</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token class-name">SyntaxShape</span><span class="token punctuation">::</span><span class="token class-name">OneOf</span><span class="token punctuation">(</span><span class="token macro property">vec!</span><span class="token punctuation">[</span><span class="token class-name">SyntaxShape</span><span class="token punctuation">::</span><span class="token class-name">GlobPattern</span><span class="token punctuation">,</span> <span class="token class-name">SyntaxShape</span><span class="token punctuation">::</span><span class="token class-name">String</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>だからrestのパースがどうなっているかを見たい。 restで検索すると、以下の所か？</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">let</span> args <span class="token operator">=</span> <span class="token keyword">crate</span><span class="token module-declaration namespace"><span class="token punctuation">::</span>parser<span class="token punctuation">::</span></span><span class="token function">parse_value</span><span class="token punctuation">(</span></span>
<span class="line">    working_set<span class="token punctuation">,</span></span>
<span class="line">    spread_arg_span<span class="token punctuation">,</span></span>
<span class="line">    <span class="token operator">&amp;</span><span class="token class-name">SyntaxShape</span><span class="token punctuation">::</span><span class="token class-name">List</span><span class="token punctuation">(</span><span class="token class-name">Box</span><span class="token punctuation">::</span><span class="token function">new</span><span class="token punctuation">(</span>rest_shape<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">None</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>rest_shapeはさっきのrestが入ってそうな雰囲気。</p><p>parse_valueはparse_expression.rsにあって、OneOfを渡しているとparse_oneofに行きそう。これはparse_calls.rsに定義されていて、 これがshape一つずつparse_valueを呼んで良さそうなのを返す、という感じっぽいので、parse_valueに戻ってくるという事か。</p><p>parse_valueの先に進むと以下がある。</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">match</span> shape <span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">SyntaxShape</span><span class="token punctuation">::</span><span class="token class-name">Number</span> <span class="token operator">=&gt;</span> <span class="token function">parse_number</span><span class="token punctuation">(</span>working_set<span class="token punctuation">,</span> span<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">SyntaxShape</span><span class="token punctuation">::</span><span class="token class-name">Float</span> <span class="token operator">=&gt;</span> <span class="token function">parse_float</span><span class="token punctuation">(</span>working_set<span class="token punctuation">,</span> span<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">SyntaxShape</span><span class="token punctuation">::</span><span class="token class-name">GlobPattern</span> <span class="token operator">=&gt;</span> <span class="token function">parse_glob_pattern</span><span class="token punctuation">(</span>working_set<span class="token punctuation">,</span> span<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token comment">// ...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>これが型に応じたパースを呼び出す所か。</p><h2 id="liteparse" tabindex="-1"><a class="header-anchor" href="#liteparse"><span>LiteParse</span></a></h2><p>パーサーのコードを読んでいると、まずLiteParseというので大きな区切りに分かれて、その後型に応じてより詳細なパースが走る構造になっている模様。</p><p>LiteParseではbare wordとか数値とかを全部Itemとして扱い、それ以外にはPipeとかAssignmentOperatorとかがある。この辺はlex.rsのTokenContentsが参考になる。</p><p>構造としては</p><ul><li>LiteBlock <ul><li>LitePipeline <ul><li>LiteCommand</li><li>...</li></ul></li><li>LitePipeline <ul><li>LiteCommand</li></ul></li></ul></li></ul><p>という感じになっている模様。</p><h2 id="改行のパイプライン" tabindex="-1"><a class="header-anchor" href="#改行のパイプライン"><span>改行のパイプライン</span></a></h2><p>改行直後にパイプ記号があるとこれはEolでは無くpipeになる。その仕組はlex.rsでやっている。</p><p>まずlexの結果は全部トークンの配列としてpushされていく。パイプラインにあったら、前のトークンがEolだったらパイプに置き換える。</p><h2 id="中括弧などはlexで処理される" tabindex="-1"><a class="header-anchor" href="#中括弧などはlexで処理される"><span>中括弧などはlexで処理される</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">def foo [x] { echo $x }</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>は、</p><ul><li>Item def</li><li>Item foo</li><li>Item <code>[x]</code></li><li>Item <code>{ echo $x }</code></li></ul><p>となるらしい。中括弧の対応はlexレベルでやっていて、Itemとして処理される。ネストもlexレベルで見ている。 対応をとるブロックの種類としては</p><div class="language-rust line-numbers-mode" data-highlighter="prismjs" data-ext="rs"><pre><code class="language-rust"><span class="line"><span class="token keyword">pub</span> <span class="token keyword">enum</span> <span class="token type-definition class-name">BlockKind</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">Paren</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">CurlyBracket</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">SquareBracket</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token class-name">AngleBracket</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>となっている。</p><h2 id="bare-wordとexpressionの区別" tabindex="-1"><a class="header-anchor" href="#bare-wordとexpressionの区別"><span>bare wordとexpressionの区別</span></a></h2><p>geminiに聞いた話なので本当に正しいかは確かめていない。</p><p>基本的にはコマンドラインのシンボルっぽいのは全部文字列として扱われるが、 パースで型が具体的なものに関してはexpressionとして扱われて、そこで式などが使える。</p><p>さらにwhereなどの一部のコマンドの場合は<code>a &gt; 10</code> が、 <code>{$it.a &gt; 10}</code> と解釈されるらしい。</p><p>Grokに聞いたらaはanyになるとか。へー。関数は複数の型を持てて、一番マッチするのが選ばられるらしい。へぇ。</p><p>パースした結果の型情報を以降のパースに使うのは、PEGとかの話題らしい。<a href="./パース.html">パース</a></p>`,68)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};